mapper.select:
select l.id
from lab l
where cast(l.id as char) = #{reference}
   or l.lab_code = #{reference}
   or l.lab_name = #{reference}
   or concat(l.lab_code, ' ', l.lab_name) = #{reference}
limit 1

select d.id
from device d
where (
    cast(d.id as char) = #{reference}
    or d.device_code = #{reference}
    or d.device_name = #{reference}
)
  and d.lab_id = #{labId}
  and coalesce(d.deleted, 0) = 0
limit 1
